import csv, json, collections, glob, itertools
from fractions import Fraction as F
def rd(f): return list(csv.DictReader(open(f)))
plan={r['run_id']:r for r in rd('plan.csv')}
launch={r['run_id']:r for r in rd('launch_log.csv')}
fin={r['run_id']:r['finished_at'] for r in rd('runtime.csv')}
evv={r['run_id']:int(round(float(r['pass_rate'])*10000)) for r in rd('eval_results.csv')}
ret={r['run_id']:r for r in rd('retention_log.csv')}
digest={r['date']:(int(r['n_runs']),int(round(float(r['sum_pass_rate'])*10000))) for r in rd('daily_digest.csv')}
suites=json.load(open('suites.json')); pol=json.load(open('retention_policy.json'))
shv={}
for f in glob.glob('recovered/*.csv'):
    for r in rd(f): shv[r['run_id']]=int(round(float(r['pass_rate_pct'])*100))
def floor_at(t):
    for v in pol['versions']:
        if v['from']<=t<v['to']: return int(round(v['floor']*10000))
    raise Exception(t)
def suite_min(k):
    s=suites[plan[k]['suite']]; return int(round(s['random_guess']*10000)) if s['scoring']=='raw' else 0
# sanity: below_retention_floor dropped_at == finished_at ; eval values >= floor at finish
assert all(ret[k]['dropped_at']==fin[k] for k in ret if ret[k]['reason']=='below_retention_floor')
bad=[k for k in evv if evv[k]<floor_at(fin[k])]; print('eval below floor',bad[:5],len(bad))
bad=[k for k in evv if evv[k]<suite_min(k)]; print('eval below suite min',len(bad))
# known & unknown
known={}; box={}
for k in launch:
    lo,hi=suite_min(k),10000
    if k in evv: known[k]=evv[k]; continue
    if k in ret:
        if ret[k]['reason']=='below_retention_floor': hi=min(hi,floor_at(ret[k]['dropped_at'])-1)
        else: lo=max(lo,floor_at(fin[k]))
    if k in shv:
        v=shv[k]; assert lo<=v<=hi,(k,lo,v,hi); known[k]=v; continue
    assert lo<=hi,(k,lo,hi)
    box[k]=(lo,hi)
print('known',len(known),'unknown',len(box))
# per-day
day_unk=collections.defaultdict(list); day_T={}
for d,(n,s) in digest.items():
    ks=[k for k in launch if fin[k][:10]==d]; assert len(ks)==n
    T=s-sum(known[k] for k in ks if k in known)
    unk=[k for k in ks if k in box]
    lo=sum(box[k][0] for k in unk); hi=sum(box[k][1] for k in unk)
    assert lo<=T<=hi,(d,lo,T,hi)
    day_unk[d]=unk; day_T[d]=T
    if unk: print(d,len(unk),'T',T,'range',lo,hi, 'slack',T-lo,hi-T)
def cfg(k): p=plan[k]; return (p['suite'],p['curriculum'],p['retrieval'],p['decoder'])
groups=collections.defaultdict(list)
for k in launch: groups[cfg(k)].append(k)
def ckey(c): return (c['suite'],c['curriculum'],c['retrieval'],c['decoder'])
def gmax(vars_, r):
    # maximize sum c x s.t. sum x = r ; vars_ = list of (c, lo, hi); returns value
    tot=sum(c*lo for c,lo,hi in vars_); rem=r-sum(lo for c,lo,hi in vars_)
    for c,lo,hi in sorted(vars_,key=lambda v:-v[0]):
        t=min(rem,hi-lo); tot+=c*t; rem-=t
    assert rem==0; return tot
def gmin(vars_, r): return -gmax([(-c,lo,hi) for c,lo,hi in vars_], r)
def width_day(vars_, r): return gmax(vars_,r)-gmin(vars_,r)
def coef(k, frm, to):
    c=F(0)
    if cfg(k)==to: c+=F(1,len(groups[to]))
    if cfg(k)==frm: c-=F(1,len(groups[frm]))
    return c
def interval(frm,to):
    base=F(0)
    for k in groups[to]:
        if k in known: base+=F(known[k],len(groups[to]))
    for k in groups[frm]:
        if k in known: base-=F(known[k],len(groups[frm]))
    lo=hi=base
    for d,unk in day_unk.items():
        if not unk: continue
        vars_=[(coef(k,frm,to),box[k][0],box[k][1]) for k in unk]
        lo+=gmin(vars_,day_T[d]); hi+=gmax(vars_,day_T[d])
    return lo/10000, hi/10000
def gwidth(frm,to,S):
    S=set(S); w=F(0)
    for d,unk in day_unk.items():
        rest=[k for k in unk if k not in S]; sk=[k for k in unk if k in S]
        if not rest: continue
        vars_=[(coef(k,frm,to),box[k][0],box[k][1]) for k in rest]
        if not sk:
            w+=width_day(vars_,day_T[d]); continue
        rlo=max(day_T[d]-sum(box[k][1] for k in sk), sum(v[1] for v in vars_))
        rhi=min(day_T[d]-sum(box[k][0] for k in sk), sum(v[2] for v in vars_))
        assert rlo<=rhi
        cands={rlo,rhi}
        base=sum(v[1] for v in vars_)
        for order in (sorted(vars_,key=lambda v:-v[0]), sorted(vars_,key=lambda v:v[0])):
            acc=base
            for c,lo,hi in order:
                acc+=hi-lo
                if rlo<=acc<=rhi: cands.add(acc)
        w+=max(width_day(vars_,r) for r in cands)
    return w/10000
q=json.load(open('queries.json')); ans={'contrasts':{},'values':{},'widths':{},'plans':{}}
for it in q['contrasts']:
    lo,hi=interval(ckey(it['from']),ckey(it['to'])); ans['contrasts'][it['id']]={'lo':float(lo),'hi':float(hi)}
    print(it['id'],float(lo),float(hi),'N',len(groups[ckey(it['from'])]),len(groups[ckey(it['to'])]))
for it in q['values']:
    f,t=ckey(it['from']),ckey(it['to']); w0=gwidth(f,t,[]); w1=gwidth(f,t,[it['run_id']])
    ans['values'][it['id']]='yes' if w1<w0 else 'no'
    print(it['id'],it['run_id'],float(w0),float(w1),ans['values'][it['id']], cfg(it['run_id']), it['run_id'] in box, fin[it['run_id']][:10])
for it in q['widths']:
    f,t=ckey(it['from']),ckey(it['to']); w=gwidth(f,t,it['recover']); ans['widths'][it['id']]=float(w); print(it['id'],float(w),float(gwidth(f,t,[])))
for it in q['plans']:
    f,t=ckey(it['from']),ckey(it['to']); tgt=F(it['target']); cands=it['candidates']; found=None
    print(it['id'],'w0',float(gwidth(f,t,[])),'target',it['target'])
    for k in range(0,len(cands)+1):
        for S in itertools.combinations(cands,k):
            if gwidth(f,t,S)<=tgt+F(1,10**7): found=(k,list(S)); break
        if found: break
    ans['plans'][it['id']]={'k':found[0],'runs':found[1]}; print(it['id'],found, float(gwidth(f,t,found[1])))
json.dump(ans,open('/app/answers.json','w'),indent=1)
